import { type ParentComponent } from "solid-js";

import { Activatable, type ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { ActiveInputDevice } from "#core/ui-next/services/input.js";

/** Props for a focusable tooltip keyword trigger. */
export type TooltipKeywordProps = ActivatableProps;

/** Shared trigger styling and interactivity for tooltip keywords. */
export const TooltipKeyword: ParentComponent<TooltipKeywordProps> = (props) => {
	return (
		<Activatable
			{...props}
			class={`tooltip-keyword cursor-pointer transition-color duration-50 ${props.class ?? ""}`}
			classList={{
				"tooltip-keyword-focus":
					ActiveInputDevice() !== InputDeviceType.Mouse && ActiveInputDevice() !== InputDeviceType.Keyboard,
				...props.classList,
			}}
			name="TooltipKeyword"
		>
			{props.children}
		</Activatable>
	);
};
